import unittest
from candidate import largest_divisor

class TestLargestDivisor(unittest.TestCase):
    def test_largest_divisor_normal_case(self):
        self.assertEqual(largest_divisor(15), 5)

    def test_largest_divisor_prime_number(self):
        self.assertEqual(largest_divisor(23), 1)

    def test_largest_divisor_even_number(self):
        self.assertEqual(largest_divisor(24), 12)

    def test_largest_divisor_multiple_of_three(self):
        self.assertEqual(largest_divisor(27), 9)

    def test_largest_divisor_single_digit(self):
        self.assertEqual(largest_divisor(7), 1)

    def test_largest_divisor_zero_input(self):
        with self.assertRaises(ValueError):
            largest_divisor(0)

    def test_largest_divisor_negative_input(self):
        with self.assertRaises(ValueError):
            largest_divisor(-10)

    def test_largest_divisor_non_integer_input(self):
        with self.assertRaises(TypeError):
            largest_divisor(10.5)

    def test_largest_divisor_none_input(self):
        with self.assertRaises(TypeError):
            largest_divisor(None)

if __name__ == '__main__':
    unittest.main()
